import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Harness adapter contract","description":"","frontmatter":{},"headers":[],"relativePath":"harnesses/adapters.md","filePath":"harnesses/adapters.md","lastUpdated":1793129665000}'),s={name:"harnesses/adapters.md"};function n(i,e,r,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="harness-adapter-contract" tabindex="-1">Harness adapter contract <a class="header-anchor" href="#harness-adapter-contract" aria-label="Permalink to &quot;Harness adapter contract&quot;">​</a></h1><p>Neottia separates generated content from host-specific paths and configuration formats. The compiler and installer receive a <code>HarnessAdapter</code>; they do not branch on Pi or OpenCode.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Purpose</th></tr></thead><tbody><tr><td><code>@neottia/harness-adapter</code></td><td>Shared types, immutable result helpers, declaration validation, and adapter registry</td></tr><tr><td><code>@neottia/pi-adapter</code></td><td>Pi paths, prompt metadata, package settings operations, and reload notices</td></tr><tr><td><code>@neottia/opencode-adapter</code></td><td>OpenCode paths, command and agent metadata, plugin and MCP operations, and restart notices</td></tr><tr><td><code>@neottia/claude-code-adapter</code></td><td>Claude Code paths, agent metadata, project MCP operations, and restart notices</td></tr></tbody></table><p>Adapters only return data. They do not read or write files, install packages, execute commands, inspect the current directory, resolve user directories, or authenticate providers. The distribution planner will resolve symbolic paths and apply approved operations.</p><h2 id="feature-support" tabindex="-1">Feature support <a class="header-anchor" href="#feature-support" aria-label="Permalink to &quot;Feature support&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Pi</th><th>OpenCode</th><th>Claude Code</th></tr></thead><tbody><tr><td>Project and global prompts</td><td>Supported</td><td>Supported as commands</td><td>Supported as commands</td></tr><tr><td>Project and global skills</td><td>Supported</td><td>Supported</td><td>Supported</td></tr><tr><td>Local extension source</td><td>Supported</td><td>Supported as plugins</td><td>Unsupported</td></tr><tr><td>Package activation</td><td>Supported through <code>settings.json#/packages</code></td><td>Supported through <code>opencode.json#/plugin</code></td><td>Project MCP through <code>.mcp.json#/mcpServers</code></td></tr><tr><td>Local and remote MCP configuration</td><td>Unsupported</td><td>Supported through <code>opencode.json#/mcp</code></td><td>Project-only through <code>.mcp.json#/mcpServers</code></td></tr><tr><td>Native primary and subagents</td><td>Unsupported</td><td>Supported</td><td>Supported</td></tr><tr><td>Prompt description</td><td>Supported</td><td>Supported</td><td>Supported</td></tr><tr><td>Prompt argument hint</td><td>Supported</td><td>Unsupported</td><td>Supported</td></tr><tr><td>Prompt agent, model, and subtask selection</td><td>Unsupported</td><td>Supported</td><td>Supported through <code>context: fork</code></td></tr><tr><td>Agent step limit</td><td>Unsupported</td><td>Supported</td><td>Supported as <code>maxTurns</code></td></tr><tr><td>Portable agent thinking setting</td><td>Unsupported</td><td>Unsupported</td><td>Supported as <code>effort</code></td></tr></tbody></table><p>Unsupported requests return typed diagnostics and no projected file or configuration operation. Neottia does not emulate missing host features with generated extensions.</p><h2 id="symbolic-paths" tabindex="-1">Symbolic paths <a class="header-anchor" href="#symbolic-paths" aria-label="Permalink to &quot;Symbolic paths&quot;">​</a></h2><p>A <code>TargetPath</code> has an anchor and safe path segments. The available anchors are <code>project</code>, <code>home</code>, and <code>xdg-config</code>. The installer supplies the absolute value for each anchor.</p><p>Pi uses these targets:</p><table tabindex="0"><thead><tr><th>Asset</th><th>Project</th><th>Global under <code>home</code></th></tr></thead><tbody><tr><td>Prompt</td><td><code>.pi/prompts/&lt;id&gt;.md</code></td><td><code>.pi/agent/prompts/&lt;id&gt;.md</code></td></tr><tr><td>Skill</td><td><code>.pi/skills/&lt;id&gt;/SKILL.md</code></td><td><code>.pi/agent/skills/&lt;id&gt;/SKILL.md</code></td></tr><tr><td>Extension</td><td><code>.pi/extensions/&lt;id&gt;.ts</code></td><td><code>.pi/agent/extensions/&lt;id&gt;.ts</code></td></tr><tr><td>Settings</td><td><code>.pi/settings.json</code></td><td><code>.pi/agent/settings.json</code></td></tr></tbody></table><p>OpenCode uses these targets:</p><table tabindex="0"><thead><tr><th>Asset</th><th>Project</th><th>Global under <code>xdg-config</code></th></tr></thead><tbody><tr><td>Command</td><td><code>.opencode/commands/&lt;id&gt;.md</code></td><td><code>opencode/commands/&lt;id&gt;.md</code></td></tr><tr><td>Skill</td><td><code>.opencode/skills/&lt;id&gt;/SKILL.md</code></td><td><code>opencode/skills/&lt;id&gt;/SKILL.md</code></td></tr><tr><td>Plugin</td><td><code>.opencode/plugins/&lt;id&gt;.ts</code></td><td><code>opencode/plugins/&lt;id&gt;.ts</code></td></tr><tr><td>Agent</td><td><code>.opencode/agents/&lt;id&gt;.md</code></td><td><code>opencode/agents/&lt;id&gt;.md</code></td></tr><tr><td>Configuration</td><td><code>opencode.json</code> or <code>opencode.jsonc</code></td><td><code>opencode/opencode.json</code> or <code>opencode/opencode.jsonc</code></td></tr></tbody></table><p>When OpenCode has no configuration file, the locator selects the <code>.json</code> candidate for creation. The installer must detect existing <code>.json</code> and <code>.jsonc</code> files before it applies a plan.</p><p>Claude Code uses these targets:</p><table tabindex="0"><thead><tr><th>Asset</th><th>Project</th><th>Global under <code>home</code></th></tr></thead><tbody><tr><td>Command</td><td><code>.claude/commands/&lt;id&gt;.md</code></td><td><code>.claude/commands/&lt;id&gt;.md</code></td></tr><tr><td>Skill</td><td><code>.claude/skills/&lt;id&gt;/SKILL.md</code></td><td><code>.claude/skills/&lt;id&gt;/SKILL.md</code></td></tr><tr><td>Agent</td><td><code>.claude/agents/&lt;id&gt;.md</code></td><td><code>.claude/agents/&lt;id&gt;.md</code></td></tr><tr><td>Configuration</td><td><code>.mcp.json</code></td><td>Unsupported</td></tr></tbody></table><p>When Claude Code has no project MCP file, the locator creates <code>.mcp.json</code>. The adapter does not edit user-managed state such as <code>~/.claude.json</code>, so MCP configuration is project-scoped only.</p><p>Asset IDs must match <code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code>. The adapters reject path separators, traversal components, and ambiguous Unicode normalization before producing a target.</p><h2 id="prompt-and-skill-output" tabindex="-1">Prompt and skill output <a class="header-anchor" href="#prompt-and-skill-output" aria-label="Permalink to &quot;Prompt and skill output&quot;">​</a></h2><p>Both adapters preserve an accepted LF-only prompt body after deterministic YAML frontmatter. Pi emits <code>description</code> and <code>argument-hint</code>. OpenCode emits <code>description</code>, <code>agent</code>, <code>model</code>, and <code>subtask</code>. Claude Code emits <code>description</code>, <code>argument-hint</code>, and <code>model</code>, and routes subagent execution through the documented <code>context: fork</code> field; an explicit <code>agent</code> selection emits both <code>context</code> and <code>agent</code>. If a request includes metadata that the host cannot represent, projection fails instead of dropping the field.</p><p>Both adapters produce the same <code>SKILL.md</code> bytes for the same skill request. Skill names use the safe asset ID format and cannot exceed 64 characters. Descriptions cannot exceed 1024 characters. Optional compatibility text must contain non-whitespace text and cannot exceed 500 characters. Optional licenses must contain non-whitespace text. Metadata keys must contain non-whitespace text, and metadata values must be strings.</p><h2 id="package-plans" tabindex="-1">Package plans <a class="header-anchor" href="#package-plans" aria-label="Permalink to &quot;Package plans&quot;">​</a></h2><p>Call <code>declarePackage()</code> with a logical module ID and exact version. The adapter owns the package-name mapping.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">adapter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">declarePackage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logicalId: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;issues&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  scope: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  version: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Pi maps this request to <code>@neottia/pi-issues</code>. OpenCode maps it to <code>@neottia/opencode-issues</code>. <code>planHostConfiguration()</code> then returns one <code>ensure-array-entry</code> operation with a stable package identity. It does not return a replacement settings document.</p><p>Claude Code maps the same logical ID to <code>@neottia/issues-mcp</code>. Its package declaration uses the <code>mcp-stdio</code> activation and produces one named <code>.mcp.json#/mcpServers</code> entry. The entry launches <code>npx --yes --package @neottia/issues-mcp@&lt;exact-version&gt; issues-mcp</code>. Package-backed MCP activation supports project scope only and preserves unrelated servers.</p><p>The four supported logical IDs are <code>memory</code>, <code>issues</code>, <code>design-docs</code>, and <code>searchable</code>. Versions must be exact SemVer 2 values. Prerelease and build metadata are accepted, while numeric components with forbidden leading zeroes are rejected. Claude Code maps them to the matching generic MCP packages and explicit executable names.</p><h2 id="mcp-plans" tabindex="-1">MCP plans <a class="header-anchor" href="#mcp-plans" aria-label="Permalink to &quot;MCP plans&quot;">​</a></h2><p>OpenCode accepts local and remote MCP declarations. Local commands remain arrays so no shell parsing is introduced. Environment and header values remain strings such as <code>{env:API_TOKEN}</code>; the adapter does not resolve them.</p><p>Claude Code accepts the same declarations for project scope only. Local servers become documented <code>type: &quot;stdio&quot;</code> entries where the first argv value is <code>command</code> and the rest move to <code>args</code>; environment values move to <code>env</code>. Remote servers become <code>type: &quot;http&quot;</code> entries. Both shapes support the documented per-server <code>timeout</code> with its 1000 millisecond minimum. The adapter rejects <code>cwd</code> and <code>enabled</code> because the shared contract has no documented Claude Code representation for them. Package-backed runtime servers use the same named MCP operation shape.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opencodeHarnessAdapter.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">planHostConfiguration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  kind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp.remote&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  scope: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;global&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  server: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;company-docs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    url: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://mcp.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    headers: { Authorization: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer {env:DOCS_TOKEN}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    oauth: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The result contains an <code>ensure-object-entry</code> operation at <code>/mcp</code>. It never creates an OAuth token or authentication file. Pi returns an unsupported-feature diagnostic for the same request because Pi has no built-in MCP settings. Claude Code returns an equivalent operation at <code>/mcpServers</code> in <code>.mcp.json</code> for project scope and a scope diagnostic for global scope. Claude Code package activation returns the same scope diagnostic for global requests.</p><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>OpenCode agent projection writes Markdown with <code>description</code>, <code>mode</code>, optional <code>model</code>, optional <code>steps</code>, and <code>permission</code>. New output uses the current <code>steps</code> and <code>permission</code> fields instead of deprecated agent fields. Claude Code agent projection writes <code>name</code>, <code>description</code>, optional <code>model</code>, optional <code>effort</code>, and optional <code>maxTurns</code>; the portable permission map has no documented agent-file field and returns a diagnostic. Pi returns an unsupported-feature diagnostic. Later role compilation decides whether a missing native agent is allowed to fall back to current-agent instructions.</p><p>OpenCode and Pi reject a portable thinking hint. Claude Code maps the thinking hint to the documented <code>effort</code> field, which accepts a bounded level set; unsupported values return a diagnostic. Provider-specific fields are not treated as portable host support.</p><h2 id="runtime-contract" tabindex="-1">Runtime contract <a class="header-anchor" href="#runtime-contract" aria-label="Permalink to &quot;Runtime contract&quot;">​</a></h2><p><code>defineHarnessAdapter()</code> snapshots the declaration and wraps every method. The wrapper validates decoded request objects before host code runs. It checks that each method returns either one value with no diagnostics or no value with at least one valid diagnostic. Success checks cover symbolic paths, config locators, projected files, package declarations, config plans and operations, and reload notices. Unsafe paths, missing fields, unknown enums, and mismatched host IDs become <code>INVALID_ADAPTER_RESULT</code>. Config operation payloads remain opaque after the wrapper checks the operation envelope and required <code>value</code> property. The registry applies this wrapper to third-party adapters and does not retain caller-owned declarations, feature records, or version arrays.</p><p>All built-in declarations leave <code>testedHostVersions</code> empty. Repository tests validate projections and plan shapes without executing a Pi, OpenCode, or Claude Code binary. A version belongs in that array only after a version-coupled host test exercises the adapter.</p><h2 id="reload-notices" tabindex="-1">Reload notices <a class="header-anchor" href="#reload-notices" aria-label="Permalink to &quot;Reload notices&quot;">​</a></h2><p>Pi resource changes produce a <code>/reload</code> notice. Pi package activation produces a restart notice because package installation occurs during startup.</p><p>OpenCode changes produce a restart recommendation for deterministic pickup. OpenCode documents startup loading for plugins, package dependencies, and MCP activation, but it does not document one reload command for every asset type. The restart message is Neottia adapter policy, not an OpenCode guarantee.</p><p>Claude Code changes also produce a restart recommendation. Claude Code watches skill directories live, but command, agent, and project MCP changes do not document a universal reload command. The restart message is Neottia adapter policy, not a Claude Code guarantee.</p><h2 id="review-and-application" tabindex="-1">Review and application <a class="header-anchor" href="#review-and-application" aria-label="Permalink to &quot;Review and application&quot;">​</a></h2><p><code>HostConfigPlan</code> supports two semantic operations:</p><ul><li><code>ensure-array-entry</code> for package activation</li><li><code>ensure-object-entry</code> for named MCP servers</li></ul><p>Each operation has a stable ID and <code>owner: &quot;neottia&quot;</code>. The future installer must parse the selected host file, preserve unrelated entries, show the operation for review, and apply it only under its ownership rules. Adapters do not implement those steps.</p>`,47)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
